mapper.update:
UPDATE `order`
SET status = 'PAID', paid_at = #{paidAt}, updated_at = #{paidAt}
WHERE order_id = #{orderId} AND status = 'PENDING_PAYMENT' AND is_deleted = 0

UPDATE `order`
SET status = 'SHIPPED', tracking_no = #{trackingNo}, updated_at = #{updatedAt}
WHERE order_id = #{orderId} AND status = 'PAID' AND is_deleted = 0

UPDATE `order`
SET status = 'COMPLETED', updated_at = #{updatedAt}
WHERE order_id = #{orderId} AND status = 'SHIPPED' AND is_deleted = 0

UPDATE `order`
SET status = 'CANCELLED', updated_at = #{updatedAt}
WHERE order_id = #{orderId} AND status = 'PENDING_PAYMENT' AND is_deleted = 0

UPDATE `order`
SET status = 'REFUNDED', updated_at = #{updatedAt}
WHERE order_id = #{orderId}
  AND status IN ('PAID', 'SHIPPED', 'COMPLETED')
  AND is_deleted = 0
